package com.alpharip.staffmod.IncidentPostMortemBoard; public final class IncidentPostMortemSummary { private final int total,open,investigating,actionRequired,resolved,critical,unfinishedActions; public IncidentPostMortemSummary(int t,int o,int i,int a,int r,int c,int u){total=t;open=o;investigating=i;actionRequired=a;resolved=r;critical=c;unfinishedActions=u;} public int getTotal(){return total;} public int getOpen(){return open;} public int getInvestigating(){return investigating;} public int getActionRequired(){return actionRequired;} public int getResolved(){return resolved;} public int getCritical(){return critical;} public int getUnfinishedActions(){return unfinishedActions;} }